#!/usr/bin/env node

import { getApplications, getStats, initDB } from "./tracker/database.js";
import { cfg, ensureDirectories } from "./config.js";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { extractText, getDocumentProxy } from "unpdf";
import { createInterface } from "node:readline/promises";
import { stdin as input, stdout as output } from "node:process";
import { runApplication } from "./worker/run-application.js";
import { parseResume } from "./evaluator/resume-parser.js";
import {
  addSupplement,
  DEFAULT_PROFILE_PATH,
  loadProfile,
  profileFromResume,
  redactProfile,
  saveProfile,
} from "./profile/profile-store.js";
import type { CandidateProfile, UnresolvedField } from "./types/index.js";

// ─── ASCII Art ─────────────────────────────────────────────────────────────────

const BANNER = `
  ╔═══════════════════════════════════════════════════════════╗
  ║                                                           ║
  ║     🚀  J O B   A G E N T                                ║
  ║     Local Job Application Assistant                       ║
  ║                                                           ║
  ║     Evaluate → Explore → Draft → Pre-fill → Review        ║
  ║                                                           ║
  ╚═══════════════════════════════════════════════════════════╝
`;

// ─── Helpers ───────────────────────────────────────────────────────────────────

function printStep(step: number, total: number, title: string): void {
  console.log(`\n${"─".repeat(60)}`);
  console.log(`  STEP ${step}/${total}: ${title}`);
  console.log(`${"─".repeat(60)}`);
}

function printScoreBar(score: number): string {
  const filled = "█".repeat(Math.round(score));
  const empty = "░".repeat(10 - Math.round(score));
  return `[${filled}${empty}] ${score}/10`;
}

function setProfileAnswer(profile: CandidateProfile, label: string, value: string): void {
  const lower = label.toLowerCase();
  if (/salary|compensation|pay expectation/.test(lower)) profile.preferences.desiredSalary = value;
  else if (/start date|available to start|earliest start/.test(lower)) profile.preferences.earliestStartDate = value;
  else if (/notice period/.test(lower)) profile.preferences.noticePeriod = value;
  else if (/visa|immigration status/.test(lower)) profile.workAuthorization.visaStatus = value;
  else if (/sponsor/.test(lower)) profile.workAuthorization.requiresSponsorship = /^y(es)?$/i.test(value);
  else if (/relocat/.test(lower)) profile.preferences.willingToRelocate = /^y(es)?$/i.test(value);
  else if (/\bcity\b/.test(lower)) profile.candidate.city = value;
  else if (/\bcountry\b/.test(lower)) profile.candidate.country = value;
  else profile.commonAnswers[label] = value;
}

async function askForMissingFields(
  fields: UnresolvedField[],
  profile: CandidateProfile,
): Promise<CandidateProfile> {
  if (!input.isTTY) return profile;
  const rl = createInterface({ input, output });
  try {
    console.log("\n  I found fields that are not supported by your saved profile.");
    console.log("  Press Enter to leave any field blank. Answers are saved locally.\n");
    for (const field of fields) {
      const value = (await rl.question(`  ${field.required ? "[required] " : ""}${field.label}: `)).trim();
      if (value) setProfileAnswer(profile, field.label, value);
    }
  } finally {
    rl.close();
  }
  return profile;
}

// ─── Commands ──────────────────────────────────────────────────────────────────

async function cmdApply(jobUrl: string, resumePath?: string): Promise<void> {
  console.log(BANNER);

  const rPath = resumePath || cfg.resumePath;

  // Validate inputs
  if (!existsSync(rPath)) {
    console.error(`\n  ❌ Resume not found: ${rPath}`);
    console.error(`  💡 Create a resume at data/resumes/placeholder.txt or set RESUME_PATH in .env`);
    process.exit(1);
  }

  try {
    await runApplication({
      jobUrl,
      resumePath: rPath,
      profilePath: DEFAULT_PROFILE_PATH,
      onQuestions: askForMissingFields,
      onProgress: (progress) => {
        printStep(1, 1, `${progress.stage.toUpperCase()} — ${progress.message}`);
      },
    });
    await new Promise<void>((resolve) => {
      const keepAlive = setInterval(() => {}, 30_000);
      process.on("SIGINT", () => {
        clearInterval(keepAlive);
        console.log("\n  👋 ApplyFlow exiting. Session stays open for your review.\n");
        resolve();
      });
    });
  } catch (err) {
    console.error(`\n  ❌ Error: ${err}`);
  }
}

async function cmdProfileInit(resumePath: string, supplementPaths: string[]): Promise<void> {
  if (!resumePath || !existsSync(resumePath)) throw new Error("Provide an existing PDF or TXT resume path.");
  let parsePath = resumePath;
  let temporaryDirectory = "";
  if (resumePath.toLowerCase().endsWith(".pdf")) {
    const bytes = new Uint8Array(readFileSync(resumePath));
    const document = await getDocumentProxy(bytes);
    const result = await extractText(document, { mergePages: true });
    temporaryDirectory = mkdtempSync(join(tmpdir(), "applyflow-profile-"));
    parsePath = join(temporaryDirectory, "resume.txt");
    writeFileSync(parsePath, result.text, { mode: 0o600 });
  } else if (!resumePath.toLowerCase().endsWith(".txt")) {
    throw new Error("Profile setup accepts PDF or TXT resumes.");
  }
  const resume = parseResume(parsePath);
  let profile = profileFromResume(resume, resumePath);
  for (const supplementPath of supplementPaths) {
    if (!existsSync(supplementPath)) throw new Error(`Supplement not found: ${supplementPath}`);
    profile = addSupplement(profile, readFileSync(supplementPath, "utf8"));
  }
  profile = await askForMissingFields([
    { label: "Country", required: true, reason: "missing_profile_data" },
    { label: "City", required: false, reason: "missing_profile_data" },
    { label: "Visa / immigration status", required: false, reason: "sensitive_field" },
    { label: "Will you require sponsorship?", required: true, reason: "sensitive_field" },
    { label: "Desired salary / compensation", required: false, reason: "sensitive_field" },
    { label: "Earliest start date", required: false, reason: "missing_profile_data" },
    { label: "Notice period", required: false, reason: "missing_profile_data" },
    { label: "Are you willing to relocate?", required: false, reason: "missing_profile_data" },
  ], profile);
  saveProfile(profile);
  if (temporaryDirectory) rmSync(temporaryDirectory, { recursive: true, force: true });
  console.log(`\n  Profile saved locally: ${DEFAULT_PROFILE_PATH}`);
}

function cmdProfileShow(): void {
  const profile = loadProfile();
  if (!profile) throw new Error("No profile found. Run `npm run profile:init -- <resume.txt>`. ");
  console.log(JSON.stringify(redactProfile(profile), null, 2));
}

function cmdProfileRemember(question: string, answer: string): void {
  const profile = loadProfile();
  if (!profile) throw new Error("No profile found. Run `npm run profile:init -- <resume.txt>` first.");
  profile.commonAnswers[question] = answer;
  saveProfile(profile);
  console.log("  Saved the answer locally. It will be reused when a similar question appears.");
}

async function cmdHistory(): Promise<void> {
  console.log(BANNER);

  initDB();

  const apps = getApplications();
  const stats = getStats();

  console.log("  📊 Application Statistics");
  console.log("  ─────────────────────────");
  console.log(`  Total applications: ${stats.total}`);
  console.log(`  Average score: ${stats.avgScore.toFixed(1)}/10`);
  for (const [status, count] of Object.entries(stats.byStatus)) {
    console.log(`  ${status}: ${count}`);
  }

  if (apps.length === 0) {
    console.log("\n  ℹ️  No applications tracked yet. Run `npm run apply` to start.\n");
    return;
  }

  console.log("\n  📋 Recent Applications");
  console.log("  ──────────────────────");

  for (const app of apps.slice(0, 10)) {
    const icon =
      app.score >= 8 ? "🟢" : app.score >= 6 ? "🟡" : app.score >= 4 ? "🟠" : "🔴";
    console.log(
      `  ${icon} ${app.company.padEnd(20)} | ${app.title.slice(0, 30).padEnd(30)} | ${app.score}/10 | ${app.status}`
    );
  }
  console.log("");
}

// ─── CLI Entry ─────────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  ensureDirectories();

  const args = process.argv.slice(2);
  const command = args[0] || "help";

  switch (command) {
    case "apply": {
      const jobUrl = args[1];
      const resumePath = args[2];

      if (!jobUrl) {
        console.error("  Usage: applyflow apply <job-url> [resume-path]");
        console.error("  Example: applyflow apply https://boards.greenhouse.io/company/jobs/12345");
        process.exit(1);
      }

      await cmdApply(jobUrl, resumePath);
      break;
    }

    case "history":
      await cmdHistory();
      break;

    case "profile:init": {
      const resumePath = args[1];
      if (!resumePath) throw new Error("Usage: applyflow profile:init <resume.pdf|resume.txt> [supplement.txt ...]");
      await cmdProfileInit(resumePath, args.slice(2));
      break;
    }

    case "profile:show":
      cmdProfileShow();
      break;

    case "profile:remember": {
      const question = args[1];
      const answer = args[2];
      if (!question || !answer) throw new Error('Usage: applyflow profile:remember "<question>" "<answer>"');
      cmdProfileRemember(question, answer);
      break;
    }

    case "help":
    case "--help":
    case "-h":
      console.log(BANNER);
      console.log("  Commands:");
      console.log("    apply <url> [resume-path]  — Evaluate, explore, draft, and pre-fill a job application");
      console.log("    history                    — View tracked applications and stats");
      console.log("    profile:init <resume.pdf|txt> [supplements...] — Build and complete your local profile");
      console.log("    profile:show               — Show the saved profile with contact details redacted");
      console.log("    profile:remember <question> <answer> — Save a confirmed reusable answer");
      console.log("    help                       — Show this help message");
      console.log("");
      console.log("  Examples:");
      console.log("    applyflow apply https://boards.greenhouse.io/stripe/jobs/12345");
      console.log("    applyflow apply https://jobs.lever.co/company/abc123 ./my-resume.txt");
      console.log("    applyflow history");
      console.log("");
      break;

    default:
      console.log(`  Unknown command: ${command}`);
      console.log("  Run `applyflow help` for usage information.");
      process.exit(1);
  }
}

main().catch((err) => {
  console.error(`\n  ❌ Fatal error: ${err}`);
  process.exit(1);
});

